alter table booking_payments add column if not exists payment_type text not null default 'deposit' check (payment_type in ('deposit','full_payment','refund'));
alter table booking_payments drop constraint if exists booking_payments_amount_check;
alter table booking_payments add constraint booking_payments_amount_check check ((payment_type = 'refund' and amount <= 0) or (payment_type <> 'refund' and amount >= 0));
alter table booking_payments add column if not exists transaction_reference text;
create unique index if not exists booking_payments_reference_idx on booking_payments(transaction_reference) where transaction_reference is not null;
insert into bookings (booking_request_id,guest_name,guest_email,guest_phone,source,check_in,check_out,guests,status,total_amount,deposit_amount,payment_status)
select id,name,email,phone,source,arrive,depart,greatest(coalesce(nullif(guests,'')::int,1),1),'confirmed',180000,90000,'partial' from booking_requests where note='[DEMO] Sample booking request' on conflict (booking_request_id) do nothing;
insert into booking_payments (booking_id,amount,method,reference,status,paid_at,payment_type,transaction_reference)
select b.id,v.amount,v.method,v.reference,v.status,now()-v.age,v.kind,v.reference from bookings b join booking_requests r on r.id=b.booking_request_id join (values ('ruwan.silva@example.com',90000::numeric,'Bank Transfer','TRX982347','verified',interval '1 day','deposit'),('priya.mendis@example.com',135000::numeric,'Credit Card','TRX982312','verified',interval '2 days','full_payment'),('dilshan.perera@example.com',67500::numeric,'Bank Transfer','TRX982301','pending',interval '2 days','deposit'),('saman.jayasuriya@example.com',90000::numeric,'Online Payment','TRX982276','verified',interval '3 days','full_payment'),('nimali.fernando@example.com',-15000::numeric,'Bank Transfer','TRX982250','refunded',interval '4 days','refund')) v(email,amount,method,reference,status,age,kind) on r.email=v.email where not exists(select 1 from booking_payments p where p.transaction_reference=v.reference);
